SELECT * FROM (
    SELECT 
        s.*, 
        ROWNUM as rnum 
    FROM (
        SELECT * FROM auction




                    AND status = #{status}


                    AND (name LIKE '%' || #{word} || '%' OR description LIKE '%' || #{word} || '%')




        ORDER BY seq DESC
    ) s
) 
WHERE rnum BETWEEN #{begin} AND #{end}

